//! The command catalog as Markdown (`docs/COMMANDS.md`, regenerated by
//! `dashcraft commands --markdown`; a test keeps the committed file in sync).

use std::fmt::Write as _;

use serde_json::{Map, Value};

use crate::command::{Category, CommandSpec};
use crate::error::OpErrorCode;
use crate::registry::Registry;

const HEADER: &str = r#"<!-- Generated from the command registry (crates/pbi-ops). Do not edit by hand:
     cargo run -q -p pbiview-cli --bin dashcraft -- commands --markdown > docs/COMMANDS.md
     (the pbi-ops test `commands_md_is_up_to_date` fails when this file is stale). -->

# Command catalog

Every DashCraft capability is a **command**: a stable dotted id, typed parameters and a typed result, both described by JSON Schema (draft 2020-12). The CLI (`dashcraft run`, `dashcraft serve`, `dashcraft mcp`), the desktop app and AI agents (MCP) all run the same commands through one registry (`pbi-ops`, [ADR-0007](adr/0007-command-registry.md)). `pbiview` is an alias of the `dashcraft` binary.

## Running commands

```sh
dashcraft commands                                   # the catalog (--json, --schemas, --markdown)
dashcraft run doc.detect -p path=model.pbip          # -p key=value (values parsed as JSON when they are JSON)
dashcraft run report.pages --doc model.pbip          # --doc opens the file first and passes its docId
dashcraft run measures.values --doc model.pbip --blob-map blob-map.json -p report=Stores --pretty
dashcraft run dax.query --doc model.pbip --params '{"query": "EVALUATE ROW(\"n\", [Total Sales])"}'
dashcraft run --batch steps.json                     # ordered steps sharing one workspace
dashcraft serve --stdio                              # JSON-lines RPC (below)
dashcraft mcp                                        # MCP server for AI agents (MCP.md)
```

- Parameters are camelCase JSON objects; unknown fields are rejected (`invalidParams`).
- Documents are opened with `doc.open`, which returns a `docId` (`d1`, `d2`, …) for the other commands. Data commands (`data.page`, `dax.*`, `measures.values`, `render.*`, `canvas.*`, `export.table`) load the data on first use unless the document was opened with `"autoRefresh": false`; `data.refresh` reloads it.
- `dashcraft run` prints the result as JSON. Exit codes: 0 success; 1 fatal or usage error; 2 the input was read but data or expressions have errors (`query` errors, or a result with `"ok": false` — failed tables, ⚠ measures, failed visuals, lint findings).

### Batches

`dashcraft run --batch FILE` (or `-` for stdin) and `commands.batch` run ordered steps on one workspace:

```json
[
  { "id": "doc.open", "params": { "path": "model.pbip", "blobMap": "blob-map.json" }, "as": "d" },
  { "id": "measures.values", "params": { "docId": "${d.docId}", "report": "Stores" } },
  { "id": "render.page", "params": { "docId": "${d.docId}", "format": "png", "outputPath": "page.png", "overwrite": true } }
]
```

A string that is exactly `${name.path}` is replaced by the referenced value of the step named `name` (any JSON type); inside a longer string the value's text is spliced in; `$${` is a literal `${`. Paths are dotted, array items by index (`${p.pages.0.name}`). Batches stop at the first error unless `"stopOnError": false` (`--stop-on-error false`); they are not atomic. The output is an array of `{ index, id, as?, ok, result?, error? }`.

### JSON-lines RPC (`dashcraft serve`)

One JSON-RPC 2.0 message per line on stdin/stdout (logs go to stderr):

```text
→ {"jsonrpc":"2.0","id":1,"method":"doc.open","params":{"path":"model.pbip"}}
← {"jsonrpc":"2.0","id":1,"result":{"docId":"d1", …}}
→ {"jsonrpc":"2.0","id":2,"method":"data.refresh","params":{"docId":"d1"}}
← {"jsonrpc":"2.0","method":"progress","params":{"id":2,"command":"data.refresh","message":"Orders: 3900 rows in 82 ms","fraction":0.25}}
→ {"jsonrpc":"2.0","method":"$/cancel","params":{"id":2}}
← {"jsonrpc":"2.0","id":2,"error":{"code":-32800,"message":"the operation was cancelled","data":{"code":"cancelled"}}}
```

- Methods are command ids; `params` is an object (absent = `{}`).
- Requests run concurrently (bounded); commands that mutate a document run one at a time per `docId`, in arrival order. Responses may arrive out of order: match them by `id`.
- Notifications (no `id`) run without a response. `$/cancel {"id": …}` cancels a running or queued request. Long-running requests send `progress` notifications (best effort).
- Errors: `{ "code": <JSON-RPC integer>, "message", "data": { "code": "<string code>", "details"? } }`. Malformed lines get `-32700` (parse error) or `-32600` (invalid request).
- `--read-root DIR` / `--write-root DIR` restrict the files commands may read and write (agents); without them paths are unrestricted.

### Error codes

| Code | JSON-RPC | Exit | Meaning |
|---|---|---|---|
"#;

const AGENTS: &str = r#"
### Agents (MCP)

Commands marked **agent-safe** are offered to AI agents by `dashcraft mcp`, a thin adapter over this registry: `tools/list` = the agent-safe commands (`id` → tool name, `summary` → description, `paramsSchema` → `inputSchema`, `outputSchema` → `outputSchema`), `tools/call` = `Registry::execute` with an `Agent` caller and a restricted path policy; progress and cancellation map to MCP `notifications/progress` and `notifications/cancelled`. Setup, client configuration, roots and tool filters: [MCP.md](MCP.md).
"#;

fn error_meaning(code: OpErrorCode) -> &'static str {
    match code {
        OpErrorCode::InvalidParams => {
            "Parameters do not match the schema, or a value is out of range"
        }
        OpErrorCode::UnknownCommand => "No command with that id",
        OpErrorCode::NotFound => {
            "A file, table, column, measure, report, page or visual does not exist"
        }
        OpErrorCode::NoDocument => "The `docId` is not open, or the document has no model / report",
        OpErrorCode::Unsupported => {
            "Unsupported or refused input, or an operation DashCraft does not implement"
        }
        OpErrorCode::PathDenied => {
            "The path policy refused a path (outside the roots, symlink or `..` escape)"
        }
        OpErrorCode::Io => "A file could not be read or written (or already exists)",
        OpErrorCode::Query => "A DAX, SQL, M or CSV evaluation failed",
        OpErrorCode::Cancelled => "The command was cancelled",
        OpErrorCode::Busy => "Too many requests in flight or documents open",
        OpErrorCode::Internal => "A bug (a panic or an unexpected failure)",
    }
}

/// `docs/COMMANDS.md` for `registry`.
#[must_use]
pub fn catalog_markdown(registry: &Registry) -> String {
    let mut out = String::from(HEADER);
    for code in OpErrorCode::ALL {
        let _ = writeln!(
            out,
            "| `{}` | {} | {} | {} |",
            code.as_str(),
            code.jsonrpc_code(),
            code.exit_code(),
            error_meaning(code)
        );
    }
    out.push_str(AGENTS);
    out.push_str("\n## Catalog\n\n");
    out.push_str("Flags: **M** mutates an open document (ordered per document) · **L** long-running (progress, cancellable) · **A** agent-safe · **W** writes files (path policy).\n\n");
    out.push_str("| Command | Summary | Flags |\n|---|---|---|\n");
    for spec in registry.list() {
        let m = &spec.meta;
        let _ = writeln!(
            out,
            "| [`{}`](#{}) | {} | {} |",
            m.id,
            anchor(m.id),
            cell(m.summary),
            flags(spec)
        );
    }
    for category in Category::ALL {
        let specs: Vec<&CommandSpec> = registry
            .list()
            .iter()
            .filter(|s| s.meta.category == category)
            .collect();
        if specs.is_empty() {
            continue;
        }
        let _ = write!(out, "\n## {}\n", category.title());
        for spec in specs {
            command_section(&mut out, spec);
        }
    }
    out
}

fn anchor(id: &str) -> String {
    id.chars()
        .filter(|c| c.is_ascii_alphanumeric())
        .flat_map(char::to_lowercase)
        .collect()
}

fn cell(text: &str) -> String {
    text.replace('|', "\\|").replace('\n', " ")
}

fn flags(spec: &CommandSpec) -> String {
    let m = &spec.meta;
    let mut f = Vec::new();
    if m.mutates_document {
        f.push("M");
    }
    if m.long_running {
        f.push("L");
    }
    if m.agent_safe {
        f.push("A");
    }
    if m.writes_files {
        f.push("W");
    }
    f.join(" ")
}

/// The catalog section of one command (title, flags, parameter and result
/// tables, examples), as Markdown.
#[must_use]
pub fn command_markdown(spec: &CommandSpec) -> String {
    let mut out = String::new();
    command_section(&mut out, spec);
    out
}

fn command_section(out: &mut String, spec: &CommandSpec) {
    let m = &spec.meta;
    let _ = write!(
        out,
        "\n### `{}`\n\n**{}.** {}\n\n",
        m.id, m.title, m.summary
    );
    let mut traits = Vec::new();
    if m.mutates_document {
        traits.push("mutates the document");
    }
    if m.long_running {
        traits.push("long-running");
    }
    traits.push(if m.agent_safe {
        "agent-safe"
    } else {
        "not offered to agents"
    });
    if m.writes_files {
        traits.push("writes files");
    }
    let _ = writeln!(out, "_{}; since {}._\n", traits.join(", "), m.since);
    let _ = writeln!(out, "Parameters:\n");
    fields_table(out, &spec.params_schema, true);
    let _ = writeln!(out, "\nResult:\n");
    fields_table(out, &spec.output_schema, false);
    if !m.examples.is_empty() {
        let _ = writeln!(out, "\nExamples:\n");
        for (title, params) in m.examples {
            let pretty = serde_json::from_str::<Value>(params)
                .ok()
                .and_then(|v| serde_json::to_string(&v).ok())
                .unwrap_or_else(|| (*params).to_owned());
            let _ = writeln!(out, "- {title}: `{}`", pretty.replace('`', "\\`"));
        }
    }
}

fn fields_table(out: &mut String, schema: &Value, params: bool) {
    let defs = schema.get("$defs").and_then(Value::as_object);
    let root = resolve(schema, defs);
    let Some(props) = root.get("properties").and_then(Value::as_object) else {
        let _ = writeln!(out, "{}", type_name(root, defs));
        return;
    };
    if props.is_empty() {
        let _ = writeln!(out, "_none_");
        return;
    }
    let required: Vec<&str> = root
        .get("required")
        .and_then(Value::as_array)
        .map(|r| r.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default();
    let _ = writeln!(out, "| Field | Type | Description |\n|---|---|---|");
    for (name, prop) in props {
        let optional = if required.contains(&name.as_str()) {
            ""
        } else if params {
            " (optional)"
        } else {
            "?"
        };
        let description = prop
            .get("description")
            .or_else(|| resolve(prop, defs).get("description"))
            .and_then(Value::as_str)
            .map(first_paragraph)
            .unwrap_or_default();
        let _ = writeln!(
            out,
            "| `{name}`{optional} | {} | {} |",
            cell(&type_name(prop, defs)),
            cell(&description)
        );
    }
}

fn first_paragraph(text: &str) -> String {
    text.split("\n\n")
        .next()
        .unwrap_or_default()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

fn resolve<'a>(schema: &'a Value, defs: Option<&'a Map<String, Value>>) -> &'a Value {
    match schema
        .get("$ref")
        .and_then(Value::as_str)
        .and_then(|r| r.strip_prefix("#/$defs/"))
        .and_then(|name| defs.and_then(|d| d.get(name)))
    {
        Some(target) => target,
        None => schema,
    }
}

fn type_name(schema: &Value, defs: Option<&Map<String, Value>>) -> String {
    if schema.as_bool() == Some(true) || schema.as_object().is_some_and(Map::is_empty) {
        return "any".to_owned();
    }
    if let Some(name) = schema
        .get("$ref")
        .and_then(Value::as_str)
        .and_then(|r| r.strip_prefix("#/$defs/"))
    {
        let target = resolve(schema, defs);
        if let Some(values) = enum_values(target) {
            return values;
        }
        return name.to_owned();
    }
    if let Some(values) = enum_values(schema) {
        return values;
    }
    for key in ["anyOf", "oneOf"] {
        if let Some(options) = schema.get(key).and_then(Value::as_array) {
            let mut names: Vec<String> = options.iter().map(|o| type_name(o, defs)).collect();
            names.dedup();
            return names.join(" | ");
        }
    }
    match schema.get("type") {
        Some(Value::String(t)) if t == "array" => {
            let items = schema
                .get("items")
                .map_or_else(|| "any".to_owned(), |i| type_name(i, defs));
            format!("{items}[]")
        }
        Some(Value::String(t)) => {
            if t == "object" && schema.get("properties").is_none() {
                "object".to_owned()
            } else {
                t.clone()
            }
        }
        Some(Value::Array(types)) => {
            let names: Vec<String> = types
                .iter()
                .filter_map(Value::as_str)
                .map(|t| {
                    if t == "array" {
                        schema.get("items").map_or_else(
                            || "any[]".to_owned(),
                            |i| format!("{}[]", type_name(i, defs)),
                        )
                    } else {
                        t.to_owned()
                    }
                })
                .collect();
            names.join(" | ")
        }
        _ => {
            if schema.get("properties").is_some() {
                "object".to_owned()
            } else {
                "any".to_owned()
            }
        }
    }
}

fn enum_values(schema: &Value) -> Option<String> {
    if let Some(values) = schema.get("enum").and_then(Value::as_array) {
        return Some(
            values
                .iter()
                .map(|v| format!("`{v}`"))
                .collect::<Vec<_>>()
                .join(" | "),
        );
    }
    if let Some(c) = schema.get("const") {
        return Some(format!("`{c}`"));
    }
    let options = schema.get("oneOf").and_then(Value::as_array)?;
    let consts: Option<Vec<String>> = options
        .iter()
        .map(|o| {
            o.get("const").map(|c| format!("`{c}`")).or_else(|| {
                o.get("enum").and_then(Value::as_array).map(|v| {
                    v.iter()
                        .map(|x| format!("`{x}`"))
                        .collect::<Vec<_>>()
                        .join(" | ")
                })
            })
        })
        .collect();
    consts.map(|c| c.join(" | "))
}
